INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (-416.5, "カリン", 20047, "ミッションをクリアして、\n報酬をゲットしましょう！", 3.099, "2023/11/16 15:00:00", "2030/01/01 14:59:59", 1, 2, 2, 53, 0.0, 20047002, 190801);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (-416.5, "カリン", 20047, "受け取ることができる\n報酬があるようです\n確認してみてください", 2.801, "2023/11/16 15:00:00", "2030/01/01 14:59:59", 1, 3, 2, 54, 0.0, 20047003, 190801);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (-416.5, "カリン", 20047, "報酬がもらえますよ！\nチェックしてみてください", 0.0, "2023/11/16 15:00:00", "2030/01/01 14:59:59", 2, 4, 2, 54, 0.0, 20047004, 190801);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (-416.5, "カリン", 20047, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", 0.0, "2023/11/16 15:00:00", "2030/01/01 14:59:59", 1, 5, 1, 57, 0.0, 20047005, 190801);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (-363.0, "カリン", 20047, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", 5.506, "2023/11/16 15:00:00", "2030/01/01 14:59:59", 1, 1, 2, 55, 0.0, 20047006, 190801);
