INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (-363.0, "カリン", 20047, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", 1.539, "2023/11/16 15:00:00", "2030/01/01 14:59:59", 2, 3, 1, 56, 0.0, 20047008, 190801);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (-363.0, "カリン", 20047, "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", 1.875, "2023/11/16 15:00:00", "2030/01/01 14:59:59", 2, 4, 1, 56, 0.0, 20047009, 190801);
